{"path": "/workspace/app/page.tsx", "content": "import { cookies, headers } from 'next/headers'

/**
 * Parse the Accept-Language header and return the user's preferred language.
 *
 * Accept-Language is a comma-separated list of language tags, each optionally
 * followed by a `q` quality value (0-1). The tag with the highest q-value is the
 * most preferred. Tags without a q-value default to 1.
 *
 * Example: "en-US,en;q=0.9,fr;q=0.8" -> "en-US"
 */
function getPreferredLanguage(acceptLanguage: string | null): string {
  if (!acceptLanguage) return 'en'

  const entries = acceptLanguage
    .split(',')
    .map((part) => part.trim())
    .filter(Boolean)
    .map((part) => {
      const [tag, ...params] = part.split(';')
      const qParam = params.find((p) => p.trim().startsWith('q='))
      const q = qParam ? parseFloat(qParam.trim().slice(2)) : 1
      return { tag: tag!.trim(), q: Number.isNaN(q) ? 1 : q }
    })
    .filter((entry) => entry.tag.length > 0)

  if (entries.length === 0) return 'en'

  entries.sort((a, b) => b.q - a.q)
  return entries[0]!.tag
}

export default async function Home() {
  // cookies() and headers() are async in Next.js 15+ and opt this route
  // into dynamic rendering, since their values are only known at request time.
  const cookieStore = await cookies()
  const headersList = await headers()

  const themeCookie = cookieStore.get('theme')
  const theme = themeCookie?.value ?? 'light'

  const preferredLanguage = getPreferredLanguage(
    headersList.get('accept-language'),
  )

  return (
    <main>
      <h1>User Preferences</h1>
      <dl>
        <dt>Theme</dt>
        <dd>{theme}</dd>
        <dt>Preferred language</dt>
        <dd>{preferredLanguage}</dd>
      </dl>
    </main>
  )
}
"}

